import json,re
t=json.load(open('/var/tmp/foundry-work/work/jit-r0-records/w/e40c81dbe818/inputs.json',encoding='utf-8'))['export']
for line in t.split('\n'):
    if line.startswith('ATLAS'):
        m=re.search(r'#(\d+)',line); o=re.search(r'owed[^:]*',line)
        print(m.group(1), '|', o.group(0).strip() if o else None, '|', line.split('::')[-1].strip()[:60] if 'QUERY' in line or 'DO NOT' in line else '')
